    },
    {
      "card_ids": ["C41"],
      "claim": "Nicorandil, a small nitro-containing drug, has approximately 75% absolute oral bioavailability, indicating that the nitro group in the query is not an obstacle to achieving F ≥ 20%.",
      "evidence_role": "supportive"
    }
